package dev.deadearth.legacy;
public final class ReflectChecks {
 public static class Target {public int field_123=4;public int alias=9;public String choose(Integer x){return "i"+x;}public String choose(String x){return "s"+x;}public String func_123(int x){return "srg"+x;}public String alias(int x){return "mcp"+x;}}
 public static void main(String[] args){Target target=new Target();if(!Reflect.get(target,"alias/field_123").equals(4))throw new AssertionError("SRG fields first");Reflect.set(target,"alias/field_123",6);if(target.field_123!=6)throw new AssertionError("cached writable field");if(!Reflect.call(target,"choose",3).equals("i3")||!Reflect.call(target,"choose","3").equals("s3"))throw new AssertionError("typed overload keys");if(!Reflect.call(target,"alias/func_123",3).equals("srg3"))throw new AssertionError("SRG methods first");long[] before=Reflect.lookupStatistics();for(int i=0;i<1000;i++)Reflect.call(target,"choose",3);long[] after=Reflect.lookupStatistics();if(after[0]-before[0]!=1000||after[1]!=before[1])throw new AssertionError("method cache not reused");if(!(Reflect.make(Target.class.getName()) instanceof Target))throw new AssertionError("constructor cache");System.out.println("ReflectChecks passed: SRG precedence, overload identity and1000 cache hits");}
}
